// Watchyard's own native settings (docs/spec/phone.md P13). Every native change goes through a
// config plugin; ios/ and android/ are generated by `expo prebuild` and never edited by hand.
//
// iOS:     NSSupportsLiveActivities = true (P12).
// Android: application android:allowBackup="false" (the keychain token never leaves the
//          phone, P3) plus dataExtractionRules and fullBackupContent that exclude every domain
//          from cloud backup and from device-to-device transfer (res/xml/wy_*.xml); SYSTEM_ALERT_WINDOW removed if a library adds it;
//          android:usesCleartextTraffic only in development builds;
//          every androidx.work artifact is forced to one version (WORK_VERSION) in
//          app/build.gradle. react-native-android-widget declares work-runtime 2.8.1 while
//          expo-widgets' androidx.glance 1.2.0-rc01 pulls work-runtime-ktx 2.7.1; work 2.8
//          merged the ktx classes into work-runtime, so both on the classpath fail
//          :app:checkDebugDuplicateClasses (OneTimeWorkRequestKt, PeriodicWorkRequestKt).
//          Forcing the group to 2.8.1 turns ktx into an empty artifact.
// Android splash (`brandSplash`): expo-splash-screen is not a dependency, so the template's
//          Theme.App.SplashScreen would show a white window. It gets the Android 12+ splash
//          attributes instead: the ink background (BRAND_INK) and the adaptive icon's foreground
//          mipmap (app.config.ts android.adaptiveIcon) as the centre icon. AppTheme's window
//          background is the same ink, so the gap between the splash and the first React frame
//          is not a white flash.
const fs = require('node:fs');
const path = require('node:path');
const {
  AndroidConfig,
  withAndroidColors,
  withAndroidManifest,
  withAndroidStyles,
  withDangerousMod,
  withAppBuildGradle,
  withInfoPlist,
} = require('expo/config-plugins');

/** The icon's ink (phone/assets/src/icon.svg), also the splash background. */
const BRAND_INK = '#17191B';
const SPLASH_STYLE = 'Theme.App.SplashScreen';
const SPLASH_ITEMS = {
  'android:windowBackground': '@color/splashscreen_background',
  'android:windowSplashScreenBackground': '@color/splashscreen_background',
  'android:windowSplashScreenAnimatedIcon': '@mipmap/ic_launcher_foreground',
};

/** Sets (or adds) a <color name=...> in a colors.xml object. Idempotent. */
function setColor(colors, name, value) {
  colors.resources = colors.resources || {};
  const list = (colors.resources.color || []).filter((c) => c.$.name !== name);
  list.push({ _: value, $: { name } });
  colors.resources.color = list;
  return colors;
}

/** Sets one <item> of a style (replacing any earlier value). */
function setItem(style, name, value) {
  style.item = (style.item || []).filter((i) => i.$.name !== name);
  style.item.push({ _: value, $: { name } });
}

/**
 * The splash style edit on a styles.xml object: the SPLASH_ITEMS set on Theme.App.SplashScreen,
 * and AppTheme's window background the same ink. Idempotent.
 */
function brandSplash(styles) {
  styles.resources = styles.resources || {};
  const all = styles.resources.style || [];
  const app = all.find((x) => x.$.name === 'AppTheme');
  if (app) setItem(app, 'android:windowBackground', '@color/splashscreen_background');
  let style = all.find((x) => x.$.name === SPLASH_STYLE);
  if (!style) {
    style = { $: { name: SPLASH_STYLE, parent: 'AppTheme' }, item: [] };
    all.push(style);
  }
  const items = (style.item || []).filter((i) => !(i.$.name in SPLASH_ITEMS));
  for (const [name, value] of Object.entries(SPLASH_ITEMS)) items.push({ _: value, $: { name } });
  style.item = items;
  styles.resources.style = all;
  return styles;
}

function withWySplash(config) {
  config = withAndroidColors(config, (c) => {
    setColor(c.modResults, 'splashscreen_background', BRAND_INK);
    return c;
  });
  return withAndroidStyles(config, (c) => {
    brandSplash(c.modResults);
    return c;
  });
}

// Every backup domain (android.app.backup): the app's data never leaves the phone by any route.
const BACKUP_DOMAINS = ['root', 'file', 'database', 'sharedpref', 'external', 'device_root', 'device_file'];
const excludes = (indent) => BACKUP_DOMAINS.map((d) => `${indent}<exclude domain="${d}" path="." />`).join('\n');

/** res/xml for android:dataExtractionRules (Android 12+): nothing for cloud backup or device transfer. */
function dataExtractionRulesXml() {
  return `<?xml version="1.0" encoding="utf-8"?>
<data-extraction-rules>
  <cloud-backup>
${excludes('    ')}
  </cloud-backup>
  <device-transfer>
${excludes('    ')}
  </device-transfer>
</data-extraction-rules>
`;
}

/** res/xml for android:fullBackupContent (Android 11 and below): nothing. */
function fullBackupContentXml() {
  return `<?xml version="1.0" encoding="utf-8"?>
<full-backup-content>
${excludes('  ')}
</full-backup-content>
`;
}

const RULES_FILES = { wy_data_extraction_rules: dataExtractionRulesXml, wy_backup_rules: fullBackupContentXml };

function withWyBackupRules(config) {
  return withDangerousMod(config, [
    'android',
    (c) => {
      const dir = path.join(c.modRequest.platformProjectRoot, 'app', 'src', 'main', 'res', 'xml');
      fs.mkdirSync(dir, { recursive: true });
      for (const [name, xml] of Object.entries(RULES_FILES)) fs.writeFileSync(path.join(dir, `${name}.xml`), xml());
      return c;
    },
  ]);
}

// Widget taps (P11): react-native-android-widget's providers open an OPEN_URI tap with an implicit
// ACTION_VIEW, which any app registering watchyard:// could answer. The generated provider classes
// (`class X extends RNWidgetProvider {}`, written by that library's own plugin) get an onReceive
// that gives the tap to dev.watchyard.link.WidgetOpen first (explicit component, watchyard://
// links only). This runs on the files the library's plugin wrote, so this plugin must be listed
// BEFORE react-native-android-widget in app.config.ts (Expo runs mods last-listed first);
// scripts/prebuild-check.mjs fails if a provider is not patched.
const PROVIDER_EMPTY = /public class (\w+) extends RNWidgetProvider \{\s*\}/;

/** The patched source of a generated provider class, or null when it is not an empty provider. Idempotent. */
function patchWidgetProvider(java) {
  if (java.includes('WidgetOpen.handle')) return java;
  if (!PROVIDER_EMPTY.test(java)) return null;
  return java
    .replace('import com.reactnativeandroidwidget.RNWidgetProvider;', 'import android.content.Context;\nimport android.content.Intent;\nimport com.reactnativeandroidwidget.RNWidgetProvider;\nimport dev.watchyard.link.WidgetOpen;')
    .replace(
      PROVIDER_EMPTY,
      'public class $1 extends RNWidgetProvider {\n  @Override\n  public void onReceive(Context context, Intent intent) {\n    if (WidgetOpen.handle(context, intent)) return;\n    super.onReceive(context, intent);\n  }\n}',
    );
}

function findProviderFiles(dir, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) findProviderFiles(p, out);
    else if (e.name.endsWith('.java') && fs.readFileSync(p, 'utf8').includes('extends RNWidgetProvider')) out.push(p);
  }
  return out;
}

function withWyWidgetOpen(config) {
  return withDangerousMod(config, [
    'android',
    (c) => {
      const java = path.join(c.modRequest.platformProjectRoot, 'app', 'src', 'main', 'java');
      for (const file of findProviderFiles(java)) {
        const out = patchWidgetProvider(fs.readFileSync(file, 'utf8'));
        if (out === null) throw new Error(`with-wy-native: ${path.basename(file)} is not a widget provider this plugin knows how to patch`);
        fs.writeFileSync(file, out);
      }
      return c;
    },
  ]);
}

const REMOVED_PERMISSIONS = ['android.permission.SYSTEM_ALERT_WINDOW'];

const WORK_VERSION = '2.8.1';
const WORK_MARKER = '// wy: align androidx.work';
const WORK_GRADLE = `
${WORK_MARKER}
configurations.all {
    resolutionStrategy.eachDependency { details ->
        if (details.requested.group == 'androidx.work') {
            details.useVersion '${WORK_VERSION}'
        }
    }
}
`;

// Idempotent: prebuild regenerates build.gradle, but a plugin may still run over one twice.
function alignWorkVersions(gradle) {
  return gradle.includes(WORK_MARKER) ? gradle : gradle + WORK_GRADLE;
}

function withWyWorkAlignment(config) {
  return withAppBuildGradle(config, (c) => {
    c.modResults.contents = alignWorkVersions(c.modResults.contents);
    return c;
  });
}

function withWyIos(config) {
  return withInfoPlist(config, (c) => {
    c.modResults.NSSupportsLiveActivities = true;
    return c;
  });
}

function withWyAndroid(config, { development }) {
  return withAndroidManifest(config, (c) => {
    const manifest = c.modResults;
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(manifest);
    app.$['android:allowBackup'] = 'false';
    app.$['android:dataExtractionRules'] = '@xml/wy_data_extraction_rules';
    app.$['android:fullBackupContent'] = '@xml/wy_backup_rules';
    if (development) {
      app.$['android:usesCleartextTraffic'] = 'true';
    } else {
      delete app.$['android:usesCleartextTraffic'];
    }
    // Library manifests are merged by Gradle, so a plain removal here would not stop them:
    // mark the permissions tools:node="remove" instead.
    manifest.manifest.$['xmlns:tools'] = manifest.manifest.$['xmlns:tools'] || 'http://schemas.android.com/tools';
    const perms = (manifest.manifest['uses-permission'] || []).filter(
      (p) => !REMOVED_PERMISSIONS.includes(p.$['android:name']),
    );
    for (const name of REMOVED_PERMISSIONS) {
      perms.push({ $: { 'android:name': name, 'tools:node': 'remove' } });
    }
    manifest.manifest['uses-permission'] = perms;
    return c;
  });
}

module.exports = function withWyNative(config, props = {}) {
  const development = props.development === true;
  config = withWyIos(config);
  config = withWyAndroid(config, { development });
  config = withWyBackupRules(config);
  config = withWyWidgetOpen(config);
  config = withWyWorkAlignment(config);
  config = withWySplash(config);
  return config;
};
module.exports.REMOVED_PERMISSIONS = REMOVED_PERMISSIONS;
module.exports.WORK_VERSION = WORK_VERSION;
module.exports.BACKUP_DOMAINS = BACKUP_DOMAINS;
module.exports.dataExtractionRulesXml = dataExtractionRulesXml;
module.exports.fullBackupContentXml = fullBackupContentXml;
module.exports.patchWidgetProvider = patchWidgetProvider;
module.exports.alignWorkVersions = alignWorkVersions;
module.exports.brandSplash = brandSplash;
module.exports.setColor = setColor;
module.exports.BRAND_INK = BRAND_INK;
module.exports.SPLASH_ITEMS = SPLASH_ITEMS;
